#!/system/bin/sh
# 在 UFI「高级功能」命令框里整段粘贴执行。
set -e
export PATH="/data/data/com.minikano.f50_sms/files:/system/bin:/system/xbin:$PATH"
mkdir -p /data/clash/Scripts
cd /data/clash/Scripts

printf '%s' '' | (base64 -d 2>/dev/null || base64 -D) > node-failover.sh
printf '%s' 'UE9SVD03Nzg4ClNFQ1JFVD0xMjM0NTYKSU5URVJWQUw9NQpFTkFCTEVEPTEKQkFUQ0g9NApERUxBWV9USU1FT1VUPTUwMDAKQ1VSTF9NQVg9Nwo=' | (base64 -d 2>/dev/null || base64 -D) > node-failover.conf
if ! grep -q clashremote-node-failover Clash.Service 2>/dev/null; then
  cp Clash.Service Clash.Service.clashremote.bak
fi
printf '%s' '' | (base64 -d 2>/dev/null || base64 -D) > Clash.Service
chmod 755 node-failover.sh Clash.Service Clash.Service.clashremote.bak

./node-failover.sh stop >/dev/null 2>&1 || true
setsid ./node-failover.sh loop >/dev/null 2>&1 </dev/null &
sleep 1
echo "==== installed ===="
ls -l node-failover.sh node-failover.conf Clash.Service Clash.Service.clashremote.bak
echo "---- pid ----"
cat node-failover.pid 2>/dev/null || echo "(no pid yet)"
pid=$(cat node-failover.pid 2>/dev/null || true)
if [ -n "$pid" ] && [ -d /proc/$pid ]; then echo "alive $pid"; else echo "NOT running"; fi
echo "---- once ----"
./node-failover.sh once || true
echo "---- status ----"
cat node-failover.status 2>/dev/null || true
echo "---- log ----"
cat node-failover.log 2>/dev/null || true
